(function () {
  'use strict';
  const p5 = window.p5;

  let sketch = null;

  function setup() {
    createCanvas(400, 400, WEBGL);
    sketch = new p5.Brush();
    sketch.scaleBrushes(2);
  }

  function draw() {
    translate(-width / 2, -height / 2);
    background("#f4efe4");
    let amount = 0.05;
    sketch.fillTexture(amount);
    let c = color(0, 0, 0, 255);
    sketch.fill(c, 200);
    sketch.beginShape();
    sketch.vertex(0, 100);
    sketch.vertex(300, 0);
    sketch.vertex(300, 300);
    sketch.vertex(0, 300);
    sketch.endShape(true);
  }
})();
