var orange = "#f87d21";
var caster = "#e04119";
var exit = "#b21719";
var hay = "#808080";
var fields = "#d6d6d6";

function setup() {
  createCanvas(400, 400, WEBGL);
  // set the background brush
  noStroke();
  fill("#f4efe4");
  // set the sun in the sky
  noFill();
  fillBleed(0.8);
  circle(200, 0, 30);
  // set the moon in the sky
  noFill();
  fillBleed(0.5);
  beginShape();
  vertex(200, 200);
  vertex(200, 240);
  vertex(180, 260);
  endShape(true);
  noStroke();
  fill(sunset);
  beginShape();
  vertex(200, 200);
  vertex(200, 300);
  vertex(220, 280);
  endShape(true);
  // set the sunset in the fields
  noFill();
  fill(sunset);
  beginShape();
  vertex(180, 260);
  vertex(200, 280);
  vertex(220, 260);
  endShape(true);
  // set the grass in the fields
  noStroke();
  fill(hay);
  for (var i = 0; i < 400; i += 10) {
    ellipse(i, 10, 10);
  }
  // set the path marking fields
  noStroke();
  fill(orange);
  beginShape();
  vertex(170, 180);
  vertex(170, 200);
  vertex(190, 200);
  vertex(190, 180);
  endShape(true);
  // set the mountain passes
  noStroke();
  fill(caster);
  for (var i = 0; i < 400; i += 50) {
    beginShape();
    vertex(200, 150);
    vertex(200 + i, 140);
    vertex(200 + i, 160);
    vertex(200, 140);
    endShape(true);
  }
}
