// Paint a sunset over green hills.
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  // Paint a very bright red sky in the top layer.
  fill("#f00");
  beginShape();
  vertex(0, 0);
  vertex(0, -50);
  vertex(400, -50);
  vertex(400, 0);
  endShape(true);

  // Paint the hills.
  fill("#00f");
  for (let i = 0; i < 3; i++) {
    brush.beginShape();
    for (let j = 0; j < 100; j++) {
      brush.vertex(j * 4, -50);
      brush.vertex(j * 4, i * 10);
    }
    brush.endShape(true);
  }

  // Paint the painted hills.
  fill("#505000");
  beginShape();
  vertex(0, 0);
  vertex(50, -50);
  vertex(50, 40);
  vertex(0, 40);
  endShape(true);

  // Paint the lights over the painted hills.
  fill("#f00");
  brush.circle(50, 10, 5);
  brush.circle(50, -10, 5);
  brush.circle(50, 30, 5);
  brush.circle(50, -30, 5);

  // Paint the small red lights.
  fill("#f00");
  for (let i = 0; i < 5; i++) {
    brush.circle(15 * (0.5 + i * 0.5), 0, 5 * (0.5 + i * 0.5));
  }

  // Paint the stars.
  fill("#f0f");
  brush.circle(50, 40, 20);
}

